package programming.Strings;
import java.util.*;
public class Replacewordbyword {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner sc=new Scanner(System.in);
String s=sc.next();
String g=sc.next();
String m=sc.next();
String v=m.replace(s, g);
System.out.println(v);
	}

}
